                return $left;
            }
            return \Inilim\SqliteParser\Grammar\Reducers::foldLeftBinaryChain(
                $left,
                \array_slice($children, 1),
            );
    }

    private static function reduceAdditive(\Phplrt\Parser\Context $ctx, mixed $children): mixed
